import fs from 'node:fs/promises';
import path from 'node:path';

const KEY = /^[a-z][a-z0-9_-]*$/;

function invalid() {
  return Object.assign(new Error('Invalid batch'), { code: 'ERR_INVALID_BATCH' });
}

function conflict() {
  return Object.assign(new Error('Batch ID already used'), { code: 'ERR_BATCH_CONFLICT' });
}

function corrupt(file) {
  return Object.assign(new Error(`Corrupt ledger file: ${file}`), { code: 'ERR_LEDGER_CORRUPT' });
}

function normalize(batch) {
  if (!batch || typeof batch.id !== 'string' || !batch.id || !Array.isArray(batch.entries)) return null;
  const entries = [];
  for (const entry of batch.entries) {
    if (!entry || typeof entry.key !== 'string' || !KEY.test(entry.key) || !Number.isSafeInteger(entry.delta)) return null;
    entries.push({ key: entry.key, delta: entry.delta });
  }
  return { id: batch.id, entries };
}

function validate(batch) {
  const result = normalize(batch);
  if (!result) throw invalid();
  return result;
}

function sameEntries(a, b) {
  return a.length === b.length && a.every((entry, i) => entry.key === b[i].key && entry.delta === b[i].delta);
}

async function read(io, file, fallback) {
  let text;
  try { text = await io.readFile(file, 'utf8'); }
  catch (error) { if (error.code === 'ENOENT') return fallback; throw error; }
  return JSON.parse(text);
}

// Stage to `<name>.tmp`, then atomically replace `<name>.json`; a failed or partial
// staging write never touches the published file.
async function save(io, directory, name, value) {
  const staging = path.join(directory, `${name}.tmp`);
  await io.writeFile(staging, JSON.stringify(value));
  await io.rename(staging, path.join(directory, `${name}.json`));
}

async function removePending(io, directory) {
  try { await io.unlink(path.join(directory, 'pending.json')); }
  catch (error) { if (error.code !== 'ENOENT') throw error; }
}

// Returns the next snapshot, or null if a resulting balance is not a safe integer.
function apply(state, batch) {
  const balances = { ...state.balances };
  for (const { key, delta } of batch.entries) {
    const value = (Object.hasOwn(balances, key) ? balances[key] : 0) + delta;
    if (!Number.isSafeInteger(value)) return null;
    balances[key] = value;
  }
  return { revision: state.revision + 1, balances, receipts: [...state.receipts, batch] };
}

// Reads durable state and computes the committed snapshot in memory, without writing.
// `publish` is set when a pending transaction still has to be written to ledger.json;
// `pending` is set when pending.json exists and must be removed.
async function load(io, directory) {
  const ledgerFile = path.join(directory, 'ledger.json');
  const pendingFile = path.join(directory, 'pending.json');
  const ledger = await read(io, ledgerFile, { revision: 0, balances: {}, receipts: [] });
  if (!ledger || !Number.isSafeInteger(ledger.revision) || !ledger.balances || typeof ledger.balances !== 'object' || !Array.isArray(ledger.receipts)) {
    throw corrupt(ledgerFile);
  }
  const raw = await read(io, pendingFile, null);
  if (raw === null) return { state: ledger, publish: false, pending: false };
  const pending = normalize(raw);
  if (!pending) throw corrupt(pendingFile);
  const receipt = ledger.receipts.find(item => item.id === pending.id);
  if (receipt) {
    // Already published; only the cleanup is unfinished.
    if (!sameEntries(receipt.entries, pending.entries)) throw corrupt(pendingFile);
    return { state: ledger, publish: false, pending: true };
  }
  const state = apply(ledger, pending);
  if (!state) throw corrupt(pendingFile);
  return { state, publish: true, pending: true };
}

async function finish(io, directory, { state, publish, pending }) {
  if (publish) await save(io, directory, 'ledger', state);
  if (pending) await removePending(io, directory);
}

export async function recoverLedger(directory, { io = fs } = {}) {
  await io.mkdir(directory, { recursive: true });
  const loaded = await load(io, directory);
  await finish(io, directory, loaded);
  return loaded.state;
}

export async function commitBatch(directory, batch, { io = fs, checkpoint } = {}) {
  batch = validate(batch);
  const loaded = await load(io, directory);
  const { state } = loaded;
  const receipt = state.receipts.find(item => item.id === batch.id);
  if (receipt && !sameEntries(receipt.entries, batch.entries)) throw conflict();
  const next = receipt ? null : apply(state, batch);
  if (!receipt && !next) throw invalid();

  // All rejections happen above; durable writes start here.
  await io.mkdir(directory, { recursive: true });
  await finish(io, directory, loaded);
  if (receipt) return state;

  await save(io, directory, 'pending', batch);
  if (checkpoint) await checkpoint('prepared');
  await save(io, directory, 'ledger', next);
  if (checkpoint) await checkpoint('published');
  await removePending(io, directory);
  if (checkpoint) await checkpoint('complete');
  return next;
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import { commitBatch, recoverLedger } from './src/ledger.js';

const b1 = { id: 'a', entries: [{ key: 'cash', delta: 5 }, { key: 'bank', delta: 2 }] };
const b2 = { id: 'b', entries: [{ key: 'cash', delta: -3 }, { key: 'cash', delta: 1 }] };
const expected = { revision: 2, balances: { cash: 3, bank: 2 }, receipts: [b1, b2] };

function faulty(failAt, mode) {
  let n = 0;
  const wrap = name => async (...args) => {
    if (n++ === failAt) {
      if (name === 'writeFile' && mode === 'partial') await fs.writeFile(args[0], String(args[1]).slice(0, 7));
      if (mode === 'after' && name !== 'writeFile') { await fs[name](...args); }
      throw Object.assign(new Error(`injected ${name}`), { code: 'EIO' });
    }
    return fs[name](...args);
  };
  return Object.fromEntries(['mkdir', 'readFile', 'writeFile', 'rename', 'unlink'].map(m => [m, wrap(m)]));
}

let cases = 0;
async function scenario(setup) {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'ledger-fault-'));
  try {
    await commitBatch(dir, b1);
    await setup(dir);
    // converge via recovery then retry of b2
    const r1 = await recoverLedger(dir);
    const r2 = await recoverLedger(dir);
    assert.deepEqual(r1, r2);
    const s = await commitBatch(dir, b2);
    assert.deepEqual(s, expected);
    assert.deepEqual(await commitBatch(dir, b2), expected);
    assert.deepEqual(await recoverLedger(dir), expected);
    // also: retry directly without recover
    cases++;
  } finally { await fs.rm(dir, { recursive: true, force: true }); }
}

for (const phase of ['prepared', 'published', 'complete']) {
  await scenario(async dir => {
    const err = new Error('stop');
    await assert.rejects(commitBatch(dir, b2, { checkpoint: async p => { if (p === phase) throw err; } }), e => e === err);
  });
  // direct retry without recover
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'ledger-fault-'));
  await commitBatch(dir, b1);
  await assert.rejects(commitBatch(dir, b2, { checkpoint: async p => { if (p === phase) throw new Error('x'); } }));
  assert.deepEqual(await commitBatch(dir, b2), expected);
  await fs.rm(dir, { recursive: true, force: true });
}

// "fail after effect" isn't in contract for rename/unlink but test robustness too ('after').
for (const mode of ['before', 'partial', 'after']) {
  for (let i = 0; i < 20; i++) {
    await scenario(async dir => {
      const phases = [];
      await commitBatch(dir, b2, { io: faulty(i, mode), checkpoint: async p => phases.push(p) }).catch(e => {
        if (!/injected/.test(e.message)) throw e;
      });
    });
  }
}

// checkpoint order
{
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'ledger-fault-'));
  const phases = [];
  await commitBatch(dir, b1, { checkpoint: async p => phases.push(p) });
  assert.deepEqual(phases, ['prepared', 'published', 'complete']);
  const before = await fs.readdir(dir);
  // conflict
  await assert.rejects(commitBatch(dir, { id: 'a', entries: [] }), { code: 'ERR_BATCH_CONFLICT' });
  // overflow invalid
  await assert.rejects(commitBatch(dir, { id: 'z', entries: [{ key: 'cash', delta: Number.MAX_SAFE_INTEGER }] }), { code: 'ERR_INVALID_BATCH' });
  await assert.rejects(commitBatch(dir, { id: 'z', entries: [{ key: 'Cash', delta: 1 }] }), { code: 'ERR_INVALID_BATCH' });
  assert.deepEqual(await fs.readdir(dir), before);
  // empty batch
  const s = await commitBatch(dir, { id: 'e', entries: [] });
  assert.equal(s.revision, 2);
  // invalid JSON
  await fs.writeFile(path.join(dir, 'pending.json'), '{bad');
  await assert.rejects(recoverLedger(dir), SyntaxError);
  await fs.unlink(path.join(dir, 'pending.json'));
  await fs.writeFile(path.join(dir, 'ledger.json'), '{bad');
  await assert.rejects(recoverLedger(dir), SyntaxError);
  await assert.rejects(commitBatch(dir, b2), SyntaxError);
  assert.equal(await fs.readFile(path.join(dir, 'ledger.json'), 'utf8'), '{bad');
  await fs.rm(dir, { recursive: true, force: true });
}
// missing dir structural invalid: no dir created
{
  const dir = path.join(os.tmpdir(), 'ledger-missing-' + process.pid);
  await assert.rejects(commitBatch(dir, { id: 'x', entries: [{ key: 'a', delta: Number.MAX_SAFE_INTEGER }, { key: 'a', delta: 1 }] }), { code: 'ERR_INVALID_BATCH' });
  await assert.rejects(fs.stat(dir), { code: 'ENOENT' });
}
console.log('ok', cases);
